_ALL_INSTRUCTIONS = {}


class _InstructionMeta(type):
    """Basic Instruction Class"""

    def __new__(
        mcs, name, bases, dct, ftype=None, required=None, defaults=None
    ):
        if ftype is None:
            ftype = name

        if required is None:
            required = []

        if defaults is None:
            defaults = {}

        cls = super().__new__(mcs, name, bases, dct)
        cls._ftype = ftype
        cls._required = required
        cls._defaults = defaults

        assert (
            ftype not in _ALL_INSTRUCTIONS
        ), f"Duplicate instruction type: {ftype}"
        _ALL_INSTRUCTIONS[ftype] = cls

        return cls

    @property
    def ftype(cls):
        """class level property for itype attribute"""
        return str(cls._ftype)

    @property
    def required(cls):
        """class level property for required attribute"""
        return list(cls._required)

    @property
    def defaults(cls):
        """class level property for defaults attribute"""
        return dict(cls._defaults)


class GenericInstruction(metaclass=_InstructionMeta, ftype="generic"):
    """Base class for instructions"""

    def __init__(self, **params):
        for key in self.__class__.required:
            assert key in params
        self._params = params
        self._protected = True
        self._sort_key = None
        self._itype = self.__class__.ftype

    def __enter__(self):
        self._protected = False

    def __exit__(self, exc_type, exc_val, exc_tb):
        self._protected = True

    def __hash__(self):
        return hash(self.ftype)

    @property
    def ftype(self):
        """class level property for itype attribute"""
        return str(self.__class__.ftype)

    @classmethod
    def _default_sort_key_generator(cls, obj):
        return tuple(str(val) for _, val in obj.params)

    def _get_sort_key(self, function=None):
        """get a sort key from the instruction"""
        if function is None:
            function = self._default_sort_key_generator(self)
        return function(self)

    @property
    def sort_key(self):
        """access protected sort key attribute"""
        if self._sort_key is None:
            self._sort_key = self._get_sort_key()
        return self._sort_key

    def keys(self):
        """dict like call to keys"""
        yield from self._params.keys()

    def items(self):
        """dict like call to items"""
        yield from self._params.items()

    def values(self):
        """dict like call to values"""
        yield from self._params.values()

    @property
    def params(self):
        """access values as list"""
        return list(self.values())

    def dict_from_keys(self, *keys, defaults=None):
        """get a dictionary from keys, filled with the values"""
        if defaults is None:
            defaults = {}
        # check params first, then check defaults, return None for miss
        return {
            key: self._params.get(key, defaults.get(key, None)) for key in keys
        }

    def get(self, key, defaults=None):
        """request a value from the data area"""
        if defaults is None:
            defaults = {}
        return self._params.get(key, defaults.get(key, None))

    @classmethod
    def from_instruction(cls, instruction):
        """generate a new instruction from an old instruction"""
        return cls(
            **{
                key: instruction.get(key, defaults=cls.defaults)
                for key in cls.required
            }
        )


class SpecificInstruction(
    GenericInstruction,
    ftype="specific",
    required=["param_a", "param_b", "param_c"],
):
    """..."""

    def __init__(self, *, param_a, param_b, param_c):
        super().__init__(
            param_a=float(param_a), param_b=param_b, param_c=param_c
        )


class MoreSpecificInstruction(
    GenericInstruction,
    ftype="more_specific",
    required=["param_a", "param_b"],
):
    """..."""


class HighlySpecificInstruction(
    GenericInstruction,
    ftype="highly_specific",
    required=["param_a"],
):
    """..."""


print(_ALL_INSTRUCTIONS)


y = HighlySpecificInstruction(param_a=42)
print(y.params)

print(
    "SpecificInstruction",
    list(
        SpecificInstruction.from_instruction(y).params,
    ),
)
print(
    "MoreSpecificInstruction",
    list(MoreSpecificInstruction.from_instruction(y).params),
)
print(
    "HighlySpecificInstruction",
    list(HighlySpecificInstruction.from_instruction(y).params),
)

x = HighlySpecificInstruction(param_a=42)
try:
    print("fooo", list(HighlySpecificInstruction.from_instruction(x)))
except TypeError as e:
    print(e)
